1128	        if (this._contactFlowStage !== "ready") {
1129	          throw new Error(
1130	            `Invalid contact flow stage for success transition: ${this._contactFlowStage}`,
1131	          );
1132	        }
1133	        this._contactFlowStage = "outtro";
1134	        this._syncContactDomState(CONTACT_THEATRE_DOM_STATE_LEAVING);
1135	        await this._wait(CONTACT_THEATRE_DOM_EXIT_DELAY_MS);
1136	        await this._playContactTheatreStep(
1137	          this._engine,
1138	          () => this._pageTheatreBinder.startAfterIntroIfNeeded(this._engine!),
1139	        );
1140	        this._syncContactSuccessMessage(detail.message);
1141	        this._contactFlowStage = "success";
1142	        this._syncContactDomState(CONTACT_THEATRE_DOM_STATE_SUCCESS);
1143	      });
1144	      detail.resolve();
1145	    } catch (error) {
1146	      this._contactFlowStage = "ready";
1147	      this._syncContactDomState(CONTACT_THEATRE_DOM_STATE_READY);
1148	      detail.reject(error);
1149	    }
1150	  }
