1264	  private _syncContactDomMotion(state: ContactDomState | null): void {
1265	    this._clearContactMotionTimers();
1266	    const blocks = this._resolveContactRevealBlocks();
1267	    const successBlocks = this._resolveContactSuccessBlocks();
1268	    const successTextNodes = this._resolveContactSuccessTextNodes();
1269	    if (state === CONTACT_THEATRE_DOM_STATE_READY) {
1270	      this._setContactBlocksDown(successBlocks);
1271	      TextReveal.setVisibleOff(successTextNodes);
1272	      this._staggerContactBlocks(blocks, true);
1273	      return;
1274	    }
1275	    if (state === CONTACT_THEATRE_DOM_STATE_LEAVING) {
1276	      this._staggerContactBlocks([...blocks].reverse(), false);
1277	      TextReveal.setVisibleOff(successTextNodes);
1278	      return;
1279	    }
1280	    if (state === CONTACT_THEATRE_DOM_STATE_SUCCESS) {
1281	      successBlocks.forEach((block) => {
1282	        block.classList.remove("is-block-reveal-down");
1283	        BlockReveal.reveal(block);
1284	      });
1285	      this._staggerContactText(successTextNodes, true);
1286	      return;
1287	    }
1288	    if (state === CONTACT_THEATRE_DOM_STATE_PENDING) {
1289	      this._hideContactBlocksImmediately(blocks);
1290	      this._hideContactBlocksImmediately(successBlocks);
1291	      TextReveal.setVisibleOff(successTextNodes);
1292	      return;
1293	    }
1294	    this._hideContactBlocksImmediately(blocks);
1295	    this._hideContactBlocksImmediately(successBlocks);
1296	    TextReveal.setVisibleOff(successTextNodes);
1297	  }
