76	  private _show(): void {
77	    const drawer = this.getElement();
78	    const trigger = this._trigger;
79	    if (!drawer || !trigger) {
80	      this._done();
81	      return;
82	    }
83	    drawer.classList.add(this._openClass);
84	    trigger.classList.add(this._openClass);
85	    this._header?.classList.add(this._openClass);
86	    this._syncAria(true);
87	    Drawer.attachLock(drawer, ScrollLock.lock());
88	    const panel = Panel.getInstance();
89	    panel.init();
90	    this._panelVisibleBeforeDrawer = panel.getVisibleState();
91	    if (this._panelVisibleBeforeDrawer) {
92	      panel.setVisibleOff();
93	    }
94	    Drawer.runOpenTransition(drawer, trigger, this._openClass, undefined, () =>
95	      this._done(),
96	    );
97	  }
98	
99	  private _hide(): void {
100	    const drawer = this.getElement();
101	    const trigger = this._trigger;
102	    if (!drawer || !trigger) {
103	      this._restorePanelAfterDrawerClose();
104	      this._done();
105	      return;
106	    }
107	    Drawer.runCloseTransition(
108	      drawer,
109	      trigger,
110	      this._header,
111	      this._openClass,
112	      () => undefined,
113	      () => {
114	        this._restorePanelAfterDrawerClose();
115	        this._done();
116	      },
117	    );
118	  }
119	
120	  private _flip(): void {
121	    this._setVisibility(!this.getVisibleState());
122	  }
123	
124	  private _onEscape(event: KeyboardEvent): void {
125	    if (event.key !== "Escape") return;
126	    if (!this.getVisibleState()) return;
127	    this.setVisibleOff();
128	    this._trigger?.focus();
129	  }
130	
131	  private _onOutside(event: MouseEvent): void {
132	    if (!this.getVisibleState()) return;
133	    const drawer = this.getElement();
134	    const trigger = this._trigger;
135	    const target = event.target;
136	    if (!(target instanceof Node) || !drawer || !trigger) return;
137	    if (drawer.contains(target) || trigger.contains(target)) return;
138	    this.setVisibleOff();
139	  }
140	
141	  private _syncAria(isVisible: boolean): void {
142	    Aria.setExpanded(this._trigger, isVisible);
143	    Aria.setControls(this._trigger, this.getElement()?.id ?? "drawer-panel");
144	    Aria.setHidden(this.getElement(), !isVisible);
145	    Aria.setExpanded(this._header, isVisible);
146	  }
147	
148	  private _restorePanelAfterDrawerClose(): void {
149	    const wasVisible = this._panelVisibleBeforeDrawer;
150	    this._panelVisibleBeforeDrawer = null;
151	    if (wasVisible === true) {
152	      Panel.getInstance().setVisibleOn();
153	    }
154	  }
155	
156	  private _done(): void {
157	    this._transitioning = false;
158	    const queuedVisible = this._queuedVisible;
159	    this._queuedVisible = null;
160	    if (typeof queuedVisible !== "boolean") return;
161	    if (queuedVisible === this.getVisibleState()) return;
162	    this._setVisibility(queuedVisible);
163	  }
164	
165	  override dispose(): void {
166	    this._trigger?.removeEventListener("click", this._onTriggerClick);
167	    document.removeEventListener("keydown", this._onDocumentKeydown);
168	    document.removeEventListener("click", this._onDocumentClick);
169	    if (this._trigger) delete this._trigger.dataset[this._boundFlagAttr];
170	    this._trigger = null;
171	    this._header = null;
172	    this._queuedVisible = null;
173	    this._panelVisibleBeforeDrawer = null;
174	    this._transitioning = false;
175	    super.dispose();
176	  }
177	}
